import{_ as d,o as s,c as i,a5 as r,j as a,a as e}from"./chunks/framework.QWVCgkrI.js";const h=JSON.parse('{"title":"GPUのメモリアクセスの合体（coalescing）：同じ32要素でも読み込みが増える理由","description":"","frontmatter":{"title":"GPUのメモリアクセスの合体（coalescing）：同じ32要素でも読み込みが増える理由","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"hardware","summary":"CUDAの1ワープで32レーンが4バイトずつ読み、連続なら4区間、2要素刻みなら8区間になる理由を追う。開始アドレスのずれ、キャッシュ、DRAM実測を区別する。","aliases":["GPUメモリアクセスの合体","メモリコアレッシング","コアレッシング","Memory Coalescing","Coalesced Access","Strided Access"],"verification":"NVIDIA CUDA C++ Best Practices GuideとNsight Computeの公式資料に照合し、WindowsのPython 3.12.4で32レーンのアドレスと区間を全列挙（2026-11-21）"}},"headers":[],"relativePath":"hardware/gpu/memory-coalescing.md","filePath":"hardware/gpu/memory-coalescing.md"}'),o={name:"hardware/gpu/memory-coalescing.md"};function n(c,t,l,p,u,m){return s(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="gpuのメモリアクセスの合体-coalescing-同じ32要素でも読み込みが増える理由" tabindex="-1">GPUのメモリアクセスの合体（coalescing）：同じ32要素でも読み込みが増える理由 <a class="header-anchor" href="#gpuのメモリアクセスの合体-coalescing-同じ32要素でも読み込みが増える理由" aria-label="Permalink to &quot;GPUのメモリアクセスの合体（coalescing）：同じ32要素でも読み込みが増える理由&quot;">​</a></h1><p>GPUで画像の値を処理するとき、隣のレーンが隣の要素を読む場合と、1個おきに読む場合を比べます。どちらも32レーンが1個ずつ値を読みますが、メモリ上でどの範囲に触れるかが変わります。<strong>メモリアクセスの合体</strong>（coalescing）は、同じワープのレーンが発行したアクセスを、ハードウェアが必要なメモリ区間にまとめる仕組みです。<a href="https://docs.nvidia.com/cuda/cuda-c-best-practices-guide/index.html#coalesced-access-to-global-memory" target="_blank" rel="noreferrer">NVIDIA CUDA C++ Best Practices Guide §10.2.1</a></p><h2 id="この記事で分かること" tabindex="-1">この記事で分かること <a class="header-anchor" href="#この記事で分かること" aria-label="Permalink to &quot;この記事で分かること&quot;">​</a></h2><p>CUDAの32レーンが読むアドレスから、32バイト区間をいくつ必要とするか数えられます。連続・2要素刻み・先頭がずれた場合を比べ、その区間数と実際のDRAM転送量や処理時間を分けて説明できます。</p><h2 id="_1レーンの読み込みと、ワープ全体の要求" tabindex="-1">1レーンの読み込みと、ワープ全体の要求 <a class="header-anchor" href="#_1レーンの読み込みと、ワープ全体の要求" aria-label="Permalink to &quot;1レーンの読み込みと、ワープ全体の要求&quot;">​</a></h2><p><strong>ワープ</strong>はCUDAで32スレッドをまとめて実行する単位で、各スレッドの位置を<strong>レーン</strong>と呼びます。ここではNVIDIA GPUの <strong>Compute Capability 6.0以降</strong> を対象に、1回のグローバルメモリの読み込み命令に全32レーンが参加し、各レーンが別の4バイト要素を1つ読むとします。<a href="/study/hardware/gpu/what-is-gpu.html">GPUとは何か</a> · <a href="https://docs.nvidia.com/cuda/cuda-c-best-practices-guide/index.html#coalesced-access-to-global-memory" target="_blank" rel="noreferrer">NVIDIA CUDA C++ Best Practices Guide §10.2.1</a></p><p>この条件では、読み込みを満たすために、32バイトの境界で区切った領域をいくつ要求するかを数えます。以下ではその1区間を<strong>セグメント</strong>と呼びます。1セグメントの中に複数のレーンのアドレスが入ると、それらをまとめられます。一部の要素だけを要求する場合でも、必要なセグメントとして1つ数えます。レーンへの割り当て順を入れ替えても、触れるセグメントの集合が同じなら個数は変わりません。<a href="https://docs.nvidia.com/cuda/cuda-c-best-practices-guide/index.html#a-simple-access-pattern" target="_blank" rel="noreferrer">NVIDIA CUDA C++ Best Practices Guide §10.2.1.1</a></p><h2 id="_32バイト境界から、連続と2要素刻みを比べる" tabindex="-1">32バイト境界から、連続と2要素刻みを比べる <a class="header-anchor" href="#_32バイト境界から、連続と2要素刻みを比べる" aria-label="Permalink to &quot;32バイト境界から、連続と2要素刻みを比べる&quot;">​</a></h2><p>配列の基準アドレスを <code>base</code> とし、32バイト境界にそろっているとします。図の番地差は <code>base</code> からのバイト数です。たとえばS0は0〜31バイト、S1は32〜63バイトです。読み込みは自然な4バイト境界にあるので、各レーンは開始番地差を32で割った整数部分から、自分が触れるセグメントを求められます。<a href="https://docs.nvidia.com/cuda/cuda-c-best-practices-guide/index.html#a-simple-access-pattern" target="_blank" rel="noreferrer">NVIDIA CUDA C++ Best Practices Guide §10.2.1.1・§10.2.1.4</a></p><ul><li><strong>連続</strong>では、レーン <code>i</code> は <code>a[i]</code> を読みます。番地差は <code>4 × i</code> で、0、4、8、…、124バイトです。8レーンずつを同じセグメントにまとめられます。</li><li><strong>2要素刻み</strong>では、レーン <code>i</code> は <code>a[2*i]</code> を読みます。番地差は <code>8 × i</code> で、0、8、16、…、248バイトです。1セグメントに入るのは4レーンずつです。</li></ul>',10),a("figure",{style:{margin:"1rem 0"}},[a("div",{role:"img","aria-label":"CUDAの32レーンのうち0、3、4、7、8、31を抜粋。連続では番地差0、12、16、28、32、124で区間はS0、S0、S0、S0、S1、S3。全レーンでS0〜S3を使い、各区間の8要素を読む。2要素刻みでは番地差0、24、32、56、64、248で区間はS0、S0、S1、S1、S2、S7。全レーンでS0〜S7を使い、各区間の4要素を読む。",style:{display:"grid",gap:"0.65rem","max-width":"42rem","font-size":"0.85em","font-variant-numeric":"tabular-nums"}},[a("div",{style:{padding:"0.5rem 0.65rem",border:"1px solid var(--vp-c-divider)","border-radius":"6px"}},[a("strong",null,"連続 · 必要なセグメントは4個"),a("div",{"data-coalescing":"contiguous",style:{display:"grid","grid-template-columns":"4.25em repeat(6, minmax(0, 1fr))","align-items":"center",gap:"0.15rem 0.25rem","text-align":"center",margin:"0.45rem 0 0.6rem"}},[a("span",{style:{"text-align":"left"}},"レーン"),a("span",{"data-lane":"0"},"0"),a("span",{"data-lane":"3"},"3"),a("span",{"data-lane":"4"},"4"),a("span",{"data-lane":"7"},"7"),a("span",{"data-lane":"8"},"8"),a("span",{"data-lane":"31"},"31"),a("span",{style:{"text-align":"left"}},"番地差 (B)"),a("span",{"data-offset":"0"},"0"),a("span",{"data-offset":"12"},"12"),a("span",{"data-offset":"16"},"16"),a("span",{"data-offset":"28"},"28"),a("span",{"data-offset":"32"},"32"),a("span",{"data-offset":"124"},"124"),a("span",{style:{"text-align":"left"}},"区間"),a("span",{"data-sector":"0"},"S0"),a("span",{"data-sector":"0"},"S0"),a("span",{"data-sector":"0"},"S0"),a("span",{"data-sector":"0"},"S0"),a("span",{"data-sector":"1"},"S1"),a("span",{"data-sector":"3"},"S3")]),a("div",{style:{display:"grid","grid-template-columns":"repeat(8, minmax(0, 1fr))",gap:"0.15rem","text-align":"center"},"data-sector-coverage":"contiguous"},[a("div",{"data-sector-id":"0","data-elements":"8",style:{"border-radius":"4px",background:"var(--vp-c-brand-soft)"}},[e("S0"),a("br"),e("8/8")]),a("div",{"data-sector-id":"1","data-elements":"8",style:{"border-radius":"4px",background:"var(--vp-c-brand-soft)"}},[e("S1"),a("br"),e("8/8")]),a("div",{"data-sector-id":"2","data-elements":"8",style:{"border-radius":"4px",background:"var(--vp-c-brand-soft)"}},[e("S2"),a("br"),e("8/8")]),a("div",{"data-sector-id":"3","data-elements":"8",style:{"border-radius":"4px",background:"var(--vp-c-brand-soft)"}},[e("S3"),a("br"),e("8/8")]),a("div",{"data-sector-id":"4","data-elements":"0",style:{"border-radius":"4px",background:"var(--vp-c-bg-soft)"}},[e("S4"),a("br"),e("—")]),a("div",{"data-sector-id":"5","data-elements":"0",style:{"border-radius":"4px",background:"var(--vp-c-bg-soft)"}},[e("S5"),a("br"),e("—")]),a("div",{"data-sector-id":"6","data-elements":"0",style:{"border-radius":"4px",background:"var(--vp-c-bg-soft)"}},[e("S6"),a("br"),e("—")]),a("div",{"data-sector-id":"7","data-elements":"0",style:{"border-radius":"4px",background:"var(--vp-c-bg-soft)"}},[e("S7"),a("br"),e("—")])])]),a("div",{style:{padding:"0.5rem 0.65rem",border:"1px solid var(--vp-c-divider)","border-radius":"6px"}},[a("strong",null,"2要素刻み · 必要なセグメントは8個"),a("div",{"data-coalescing":"stride2",style:{display:"grid","grid-template-columns":"4.25em repeat(6, minmax(0, 1fr))","align-items":"center",gap:"0.15rem 0.25rem","text-align":"center",margin:"0.45rem 0 0.6rem"}},[a("span",{style:{"text-align":"left"}},"レーン"),a("span",{"data-lane":"0"},"0"),a("span",{"data-lane":"3"},"3"),a("span",{"data-lane":"4"},"4"),a("span",{"data-lane":"7"},"7"),a("span",{"data-lane":"8"},"8"),a("span",{"data-lane":"31"},"31"),a("span",{style:{"text-align":"left"}},"番地差 (B)"),a("span",{"data-offset":"0"},"0"),a("span",{"data-offset":"24"},"24"),a("span",{"data-offset":"32"},"32"),a("span",{"data-offset":"56"},"56"),a("span",{"data-offset":"64"},"64"),a("span",{"data-offset":"248"},"248"),a("span",{style:{"text-align":"left"}},"区間"),a("span",{"data-sector":"0"},"S0"),a("span",{"data-sector":"0"},"S0"),a("span",{"data-sector":"1"},"S1"),a("span",{"data-sector":"1"},"S1"),a("span",{"data-sector":"2"},"S2"),a("span",{"data-sector":"7"},"S7")]),a("div",{style:{display:"grid","grid-template-columns":"repeat(8, minmax(0, 1fr))",gap:"0.15rem","text-align":"center"},"data-sector-coverage":"stride2"},[a("div",{"data-sector-id":"0","data-elements":"4",style:{"border-radius":"4px",background:"var(--vp-c-brand-soft)"}},[e("S0"),a("br"),e("4/8")]),a("div",{"data-sector-id":"1","data-elements":"4",style:{"border-radius":"4px",background:"var(--vp-c-brand-soft)"}},[e("S1"),a("br"),e("4/8")]),a("div",{"data-sector-id":"2","data-elements":"4",style:{"border-radius":"4px",background:"var(--vp-c-brand-soft)"}},[e("S2"),a("br"),e("4/8")]),a("div",{"data-sector-id":"3","data-elements":"4",style:{"border-radius":"4px",background:"var(--vp-c-brand-soft)"}},[e("S3"),a("br"),e("4/8")]),a("div",{"data-sector-id":"4","data-elements":"4",style:{"border-radius":"4px",background:"var(--vp-c-brand-soft)"}},[e("S4"),a("br"),e("4/8")]),a("div",{"data-sector-id":"5","data-elements":"4",style:{"border-radius":"4px",background:"var(--vp-c-brand-soft)"}},[e("S5"),a("br"),e("4/8")]),a("div",{"data-sector-id":"6","data-elements":"4",style:{"border-radius":"4px",background:"var(--vp-c-brand-soft)"}},[e("S6"),a("br"),e("4/8")]),a("div",{"data-sector-id":"7","data-elements":"4",style:{"border-radius":"4px",background:"var(--vp-c-brand-soft)"}},[e("S7"),a("br"),e("4/8")])])])]),a("figcaption",{style:{"font-size":"0.875rem","margin-top":"0.55rem"}},"各図の上は6レーンの「レーン → 番地差 → セグメント」。下は全32レーンについて、各セグメントの8要素のうち何個を読むか。—は触れない区間。")],-1),r('<p>全レーンが要求した要素はどちらも32個、合計128バイトです。1ワープについて必要セグメントの大きさを足すと、連続は <code>4 × 32 = 128</code> バイト、2要素刻みは <code>8 × 32 = 256</code> バイトです。この読み込みに使う要素の割合は、連続で100%、2要素刻みで50%になります。ここで足した量は、必要な区間の合計です。<a href="https://docs.nvidia.com/cuda/cuda-c-best-practices-guide/index.html#strided-accesses" target="_blank" rel="noreferrer">NVIDIA CUDA C++ Best Practices Guide §10.2.1.4</a></p><h2 id="連続でも、先頭が4バイトずれると5区間" tabindex="-1">連続でも、先頭が4バイトずれると5区間 <a class="header-anchor" href="#連続でも、先頭が4バイトずれると5区間" aria-label="Permalink to &quot;連続でも、先頭が4バイトずれると5区間&quot;">​</a></h2><p>同じ配列で、各レーンが1つ先の <code>a[i+1]</code> を読むとします。番地差は4、8、…、128。各レーンの要素は4バイト境界にそろっていますが、ワープの読み始めは32バイト境界からずれました。先頭の要素はS0にあり、最後の要素のバイト128〜131はS4に入ります。必要なのはS0〜S4の5セグメントです。<a href="https://docs.nvidia.com/cuda/cuda-c-best-practices-guide/index.html#a-sequential-but-misaligned-access-pattern" target="_blank" rel="noreferrer">NVIDIA CUDA C++ Best Practices Guide §10.2.1.2</a></p><table tabindex="0"><thead><tr><th>読み方</th><th>触れる区間</th><th style="text-align:right;">区間の合計</th></tr></thead><tbody><tr><td>連続</td><td>S0〜S3（4個）</td><td style="text-align:right;">128 B</td></tr><tr><td>2要素刻み</td><td>S0〜S7（8個）</td><td style="text-align:right;">256 B</td></tr><tr><td>先頭を4 Bずらす</td><td>S0〜S4（5個）</td><td style="text-align:right;">160 B</td></tr></tbody></table><h2 id="セグメント数と、メモリから実際に運ぶ量" tabindex="-1">セグメント数と、メモリから実際に運ぶ量 <a class="header-anchor" href="#セグメント数と、メモリから実際に運ぶ量" aria-label="Permalink to &quot;セグメント数と、メモリから実際に運ぶ量&quot;">​</a></h2><p>セグメント数が増えても、すべての区間をそのたびにDRAMから取り直すとは限りません。たとえば先頭をずらした連続アクセスでは、次のワープも最初のワープの末尾と同じS4に触れます。同じ区間のデータがキャッシュに残っていれば再利用できます。NVIDIAのガイドには、Tesla V100での <code>offsetCopy</code> の比較があります。ずれたときの実効帯域は、区間数だけで見た4/5より落ち幅が小さく、整列時の約9/10でした。これはそのコピー処理の測定値です。<a href="https://docs.nvidia.com/cuda/cuda-c-best-practices-guide/index.html#effects-of-misaligned-accesses" target="_blank" rel="noreferrer">NVIDIA CUDA C++ Best Practices Guide §10.2.1.3</a></p><p>2要素刻みも、8対4という比だけでは実際のDRAM転送量やGPU時間を予測できません。キャッシュで何バイト吸収されたか、同じデータが後で使われるか、カーネルにほかの読み書きや演算があるかで変わります。計測では、ワープの要求を満たすセグメントと、L2やDRAMの境界を通った量を分けます。<strong>Rooflineモデル</strong>でDRAM帯域を使うなら、演算強度の分母は同じDRAM境界の転送量にそろえます。<a href="https://docs.nvidia.com/nsight-compute/ProfilingGuide/index.html#quantities" target="_blank" rel="noreferrer">NVIDIA Nsight Compute Profiling Guide — Quantities</a> · <a href="/study/hardware/gpu/roofline-model.html">Rooflineモデル</a></p><h2 id="要点" tabindex="-1">要点 <a class="header-anchor" href="#要点" aria-label="Permalink to &quot;要点&quot;">​</a></h2><ul><li>CUDAのこの例では、同じワープのレーンが1回の命令で触れる32バイト区間を数えます。</li><li>32レーンが4バイトずつ読む場合、32バイト境界から連続なら4区間、2要素刻みなら8区間です。連続でも頭を4バイトずらすと5区間になります。</li><li>必要区間の合計は、DRAMを実際に通った量とは別です。キャッシュの再利用などで、区間数と処理時間の比は一致しないことがあります。</li><li>Rooflineで帯域を調べるときは、バイト数と帯域を同じメモリ階層でそろえます。</li></ul><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><details class="details custom-block"><summary>連続と2要素刻みはどちらも128バイトぶんの値を読む。区間数が違うのはなぜ？</summary><p>連続なら8レーンぶんのアドレスが同じ32バイト区間に収まります。2要素刻みなら同じ区間から4レーンぶんしか読まないため、32レーン全体で8区間が必要です。</p></details><details class="details custom-block"><summary>+4 Bの例で5区間必要なら、毎回DRAMから160 B読む？</summary><p>160 Bは1ワープが必要とする区間の大きさの合計です。隣接ワープが同じ区間をキャッシュから再利用できる場合があり、DRAMの転送量は別に計測します。</p></details><h2 id="検証範囲" tabindex="-1">検証範囲 <a class="header-anchor" href="#検証範囲" aria-label="Permalink to &quot;検証範囲&quot;">​</a></h2><p>2026年11月21日にNVIDIAの公式資料を確認し、WindowsのPython 3.12.4で32レーンのアドレスを全列挙して、図・表のセグメント数とバイト数を照合しました。掲載したV100の実効帯域の比はガイドの測定例です。教材の3パターンはGPUで実行しておらず、DRAM転送量や実行時間は測定していません。</p><h2 id="関連項目" tabindex="-1">関連項目 <a class="header-anchor" href="#関連項目" aria-label="Permalink to &quot;関連項目&quot;">​</a></h2><ul><li><a href="/study/hardware/gpu/what-is-gpu.html">GPUとは何か</a> — GPUが多くの要素を並行して処理する理由を読む。</li><li><a href="/study/hardware/gpu/architecture.html">GPUアーキテクチャ詳解</a> — ワープ、キャッシュ、GPUの主メモリの関係を確認する。</li><li><a href="/study/graphics/compute/execution-model.html">GPU実行モデル</a> — WarpやWaveの実行と、データの並びがメモリアクセスに与える影響を読む。</li><li><a href="/study/hardware/gpu/roofline-model.html">Rooflineモデル</a> — 計測した転送量から演算強度と性能上限を考える。</li></ul><h2 id="参考資料" tabindex="-1">参考資料 <a class="header-anchor" href="#参考資料" aria-label="Permalink to &quot;参考資料&quot;">​</a></h2><ul><li><a href="https://docs.nvidia.com/cuda/cuda-c-best-practices-guide/index.html#coalesced-access-to-global-memory" target="_blank" rel="noreferrer">NVIDIA — CUDA C++ Best Practices Guide 13.5 §10.2.1</a> — 32バイト区間への合体、開始位置のずれ、2要素刻み、Tesla V100での測定。</li><li><a href="https://docs.nvidia.com/nsight-compute/ProfilingGuide/index.html#quantities" target="_blank" rel="noreferrer">NVIDIA — Nsight Compute Profiling Guide, Quantities</a> — 要求とセクターの区別、キャッシュとDRAMの計測。</li></ul>',18)])])}const b=d(o,[["render",n]]);export{h as __pageData,b as default};
